#include "ccad_core/router_tool.hpp"
#include "ccad_core/model.hpp"
#include <cassert>
int main() { ccad::Board b; ccad::Pad p; p.net_id="N1"; p.position={ccad::millimeters(4),ccad::millimeters(2)}; b.pads.push_back(p); ccad::RouterTool r; r.setBoard(&b); r.setActiveNet("N1"); r.startRouting(1,2,0); r.updateRouting(3.6,2); r.commitRouting(); assert(b.tracks.size()==1); assert(b.tracks[0].end.x.nanometers==ccad::millimeters(4).nanometers); assert(b.tracks[0].net_id=="N1"); ccad::Pad blocker; blocker.net_id="N2"; blocker.position={ccad::millimeters(6),ccad::millimeters(2)}; b.pads.push_back(blocker); r.startRouting(5,2,0); r.updateRouting(7,2); r.commitRouting(); assert(b.tracks.size()==1); ccad::TrackSegment obstacle{.id="X",.net_id="N2",.layer_id="F.Cu",.start={ccad::millimeters(8),ccad::millimeters(1)},.end={ccad::millimeters(8),ccad::millimeters(4)},.width=ccad::millimeters(0.25)}; b.tracks.push_back(obstacle); r.startRouting(7,2,0); r.updateRouting(9,2); r.commitRouting(); assert(b.tracks.size()==2); ccad::Via via{.id="V2",.net_id="N2",.position={ccad::millimeters(11),ccad::millimeters(2)},.diameter=ccad::millimeters(0.8),.drill=ccad::millimeters(0.4)}; b.vias.push_back(via); r.routeTrack(10,2,12,2); assert(b.tracks.size()==2); ccad::BoardZone zone{.id="Z2",.net_id="N2",.layer_ids={"F.Cu"},.outline={{ccad::millimeters(14),ccad::millimeters(1)},{ccad::millimeters(16),ccad::millimeters(1)},{ccad::millimeters(16),ccad::millimeters(3)},{ccad::millimeters(14),ccad::millimeters(3)}},.clearance=ccad::millimeters(0.2),.fill_enabled=true}; b.zones.push_back(zone); r.routeTrack(13,2,17,2); assert(b.tracks.size()==2); ccad::TrackSegment distant{.id="D",.net_id="N2",.layer_id="F.Cu",.start={ccad::millimeters(20),ccad::millimeters(2)},.end={ccad::millimeters(21),ccad::millimeters(2)},.width=ccad::millimeters(0.25)}; b.tracks.push_back(distant); r.routeTrack(18,2,19,2); assert(b.tracks.size()==4); r.routeTrack(7,1,9,3); assert(b.tracks.size()==4); r.startRouting(2,2,1); r.updateRouting(3,3); r.cancelRouting(); assert(b.tracks.size()==4); r.routeTrack(5,5,6,5); assert(b.tracks.size()==5); r.routeTrack(10,10,12,12); assert(b.tracks.size()==7); }
